import { NeedleError } from './errors.js';

/** Insertion of a block of lines into an existing file, just before the line that carries a needle. */
export interface FileEdit {
  readonly path: string;
  /** Short name of the needle: `main-imports` designates the line that contains `crafttype-needle-main-imports`. */
  readonly needle: string;
  readonly content: string;
}

const NEEDLE_PREFIX = 'crafttype-needle-';
const NEEDLE_NAME = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/;

export const isValidNeedleName = (name: string): boolean => NEEDLE_NAME.test(name);

/** Text to place in the generated file, in a comment specific to its language: `// crafttype-needle-x`. */
export const needleToken = (name: string): string => `${NEEDLE_PREFIX}${name}`;

/**
 * Inserts the block before the needle line, with the indentation of that line. The needle stays in place for the
 * following modules. If the block is already in the file (same lines, ignoring indentation), the content is returned
 * as is: reapplying a module duplicates nothing.
 *
 * The needle must appear exactly once: a file where it is missing or repeated was edited by hand, and
 * guessing the place could break the team's code.
 */
export const insertAtNeedle = (fileContent: string, { path, needle, content }: FileEdit): string => {
  const eol = fileContent.includes('\r\n') ? '\r\n' : '\n';
  const lines = fileContent.split(eol);
  const token = needleToken(needle);
  // The character that follows must not extend the name: `main` does not designate `main-imports`.
  const pattern = new RegExp(`${token.replaceAll(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![\\w-])`);

  const found = lines.flatMap((line, index) => (pattern.test(line) ? [{ index, line }] : []));
  const [first] = found;
  if (first === undefined) {
    throw new NeedleError(
      path,
      token,
      'needle not found: the file was modified, or generated by an older version of the module that creates it. ' +
        'Add by hand a comment line containing this needle where the code must be inserted',
    );
  }
  if (found.length > 1) {
    throw new NeedleError(path, token, `needle present ${found.length} times: it must be unique`);
  }

  const block = content.replace(/(\r?\n)+$/, '').split(/\r?\n/);
  if (containsLines(lines, block)) {
    return fileContent;
  }

  // The needle line holds the token, so it has a non-blank character: what precedes it is its indentation.
  const indent = first.line.replace(/[^ \t][^]*$/, '');
  const indented = block.map((line) => (line.trim() === '' ? '' : `${indent}${line}`));
  return [...lines.slice(0, first.index), ...indented, ...lines.slice(first.index)].join(eol);
};

const containsLines = (lines: readonly string[], block: readonly string[]): boolean => {
  const wanted = block.map((line) => line.trim());
  const existing = lines.map((line) => line.trim());
  return existing.some((_, start) => wanted.every((line, offset) => existing[start + offset] === line));
};
